ST.xhtml:p:
FBMiddleAxisAct();
FBMiddleAxisRel();
FBMiddleAxisAbs();
FBMiddleAxisJog();
FBMiddleAxisHome();
FBMiddleAxisPower();
FBMiddleAxisGearControl();
FBMiddleAxisDetection();
FBMiddleCylinderControl();
FBFeedAxisSelfTuning();
(*刷新主轴状态*)
FBReadMasterAxisStatus(
AXIS := Axis_Y0);


bAxis1ErrorAlarm :=  AntiRejection5.NCTOPLC.POWERPOSWARN OR AntiRejection5.NCTOPLC.POWERNEGWARN 
     OR AntiRejection5.NCTOPLC.ERRORCODE <>0;
bAxis2ErrorAlarm :=  AntiRejection4.NCTOPLC.POWERPOSWARN OR AntiRejection4.NCTOPLC.POWERNEGWARN 
     OR AntiRejection4.NCTOPLC.ERRORCODE <>0;



IF bAxis1ErrorAlarm AND g_bPlcResetBuffer THEN
  g_AntiRejection5Reset.Execute := TRUE;
ELSE
  g_AntiRejection5Reset.Execute := FALSE;   
END_IF;
IF bAxis2ErrorAlarm AND g_bPlcResetBuffer THEN
  g_AntiRejection4Reset.Execute := TRUE;
ELSE
  g_AntiRejection4Reset.Execute := FALSE;   
END_IF;


IF Axis_Y0.NCTOPLC.ERRORCODE <>0 AND g_bPlcResetBuffer THEN
  g_Y0Reset.EXECUTE := TRUE;
ELSE
  g_Y0Reset.EXECUTE := FALSE;
END_IF;
